import{_ as t,o as d,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const h=JSON.parse('{"title":"Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":null}'),r={name:"reference/commands.md"};function c(s,e,l,n,i,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Quick reference for all Makefile commands. For full syntax, flags, and example output, use the per-command pages under <a href="/ocapi-docs.github.io/cli/">Commands</a>.</p><h2 id="command-summary" tabindex="-1">Command summary <a class="header-anchor" href="#command-summary" aria-label="Permalink to &quot;Command summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>make setup</code></td><td>Configure brand, data source, and SFCC (OCAPI). Runs a wizard and saves config.</td></tr><tr><td><code>make switch [BRAND=]</code></td><td>Toggle brand (no arg: loft ↔ ann). Or <code>make switch BRAND=ann</code> for specific brand.</td></tr><tr><td><code>make pull</code></td><td>Git pull, fetch latest data (Excel/Smartsheet), auto-build new dates. Does not open status — run <code>make status</code> after.</td></tr><tr><td><code>make refresh</code></td><td>Build selected refresh (dev files + payload).</td></tr><tr><td><code>make push</code></td><td>Validate and sync selected refresh(es) to SFCC staging.</td></tr><tr><td><code>make status</code></td><td>Interactive hub: pick a refresh and run core actions (build, push, upload, delete, detail, pull).</td></tr><tr><td><code>make delete DATE=</code></td><td>Remove a refresh from SFCC and locally. <strong>DATE= is required to delete;</strong> omit DATE (run <code>make delete</code> with no args) to list deletable refreshes. Use <code>REFRESH=r1</code> when the date has multiple refreshes.</td></tr><tr><td><code>make upload</code></td><td>Partial asset sync (HTML changes only).</td></tr><tr><td><code>make reports [OP=coverage]</code></td><td>Visibility reports: <code>report</code> (per-refresh zone/IPID table), <code>history</code> (zone timeline), <code>coverage</code> (IPID coverage).</td></tr><tr><td><code>make test</code></td><td>Run all tests. Use <code>test-watch</code> for watch mode and <code>test-coverage</code> for coverage.</td></tr><tr><td><code>make fresh-install</code></td><td>Full reset: remove dev-env and node_modules, reinstall, then run tests.</td></tr><tr><td><code>make convert-excel INPUT=</code></td><td>Convert raw Excel to CONVERTED format (INPUT required).</td></tr><tr><td><code>make check</code></td><td>Lint, tests, and audit (CI gate).</td></tr><tr><td><code>make clean</code></td><td>Remove rendered previews.</td></tr><tr><td><code>make docs</code></td><td>Generate API docs and start the docs dev server.</td></tr><tr><td><code>make docs-gen</code></td><td>Regenerate API and template reference docs.</td></tr><tr><td><code>make docs-build</code></td><td>Generate docs and build the static site.</td></tr><tr><td><code>make docs-deploy</code></td><td>Build and deploy docs to GitHub Pages.</td></tr><tr><td><code>make lint-docs</code></td><td>Lint action types in doc files.</td></tr><tr><td><code>make test-sync DATE=</code></td><td>Push to OCAPI with auto-confirm (for CI).</td></tr><tr><td><code>make build-all [FORCE=1]</code></td><td>Build every date for the current brand.</td></tr><tr><td><code>make push-all [YES=1] [FORCE=1]</code></td><td>Sync every date to SFCC (run after build-all).</td></tr><tr><td><code>make doctor</code></td><td>Validate setup, config, brand, source, refresh dirs, and OCAPI env. Also prints config summary.</td></tr></tbody></table><details><summary><strong>⚠️ Destructive / test-use-only commands (not for routine producer use)</strong></summary><p>These commands can delete data, overwrite many campaigns, or wipe local state. For testing or when explicitly directed; do not use in normal workflow.</p><table tabindex="0"><thead><tr><th>Command</th><th>Risk</th></tr></thead><tbody><tr><td><code>make fresh-install</code></td><td><strong>Destructive.</strong> Removes <code>dev-env</code> and <code>node_modules</code>, then reinstalls. All local state and built data are lost.</td></tr><tr><td><code>make delete DATE=...</code></td><td><strong>Destructive.</strong> Removes a refresh from SFCC and locally. Can remove live or synced content. Requires <code>DATE=</code>; use <code>REFRESH=r1</code> if the date has multiple refreshes.</td></tr><tr><td><code>make push-all [YES=1]</code></td><td><strong>Loose cannon.</strong> Pushes every date for the brand to SFCC. With <code>YES=1</code> there are no confirmation prompts. Use only for CI or when a developer directs.</td></tr><tr><td><code>make test-sync</code></td><td><strong>Testing only.</strong> Sync with auto-confirm (<code>--yes --force</code>). For CI/automation, not daily use.</td></tr><tr><td><code>make docs-deploy</code></td><td><strong>Publishing.</strong> Deploys docs to GitHub Pages. Only the doc owner should run this.</td></tr><tr><td><code>make clean</code></td><td>Removes all rendered preview files. Use only if a developer asks you to free space or reset previews.</td></tr><tr><td><code>make build-all [FORCE=1]</code></td><td>Rebuilds every date for the brand. Batch/dev use; not for normal producer workflow.</td></tr><tr><td><code>make convert-excel INPUT=...</code></td><td>Converts raw Excel; can overwrite files. Dev-only.</td></tr></tbody></table><p><strong>Flags to avoid unless a developer tells you:</strong> Do not use <strong><code>YES=1</code></strong> (skips all approval prompts) or <strong><code>FORCE=1</code></strong> (bypasses &quot;already built&quot; / &quot;already synced&quot; guards) unless a developer explicitly asks you to.</p></details><p><strong>Test commands:</strong> Run <code>make test</code> for the full suite. Use <code>make test-watch</code> for watch mode and <code>make test-coverage</code> for coverage. Use <code>make fresh-install</code> for a full reset (deps + dev-env) then tests. To run a subset by path: <code>npx vitest run tests/domain</code> or <code>npx vitest run tests/cli</code>.</p><p><strong>Approval guards:</strong> When data has already been built or synced and you run <code>make push</code> again, the tool shows what changed and asks for approval. Use <code>FORCE=1</code> to skip the prompt (e.g., in CI). Use <code>YES=1</code> to auto-approve.</p><p><strong>build-all / push-all:</strong> For dev/CI batch runs. Run <code>make pull</code> first (auto-builds new dates); then <code>make build-all</code> to rebuild all dates; then <code>make push-all</code> to sync all of them to SFCC. Use <code>YES=1</code> to skip confirmation prompts. Use <code>FAIL_FAST=1</code> to stop on first failure (default: continue on error).</p><p><strong>Automation:</strong> For scripts and CI, use <code>DATE=</code>, <code>REFRESH=</code>, <code>YES=1</code>, <code>FORCE=1</code> as needed. Use <code>VERBOSE=1</code> for run IDs on log lines. Use <code>FAIL_FAST=1</code> for fail-fast batch runs, and <code>ARGS=&quot;...&quot;</code> to pass extra CLI flags.</p><h2 id="make-variables-→-cli-flags" tabindex="-1">Make variables → CLI flags <a class="header-anchor" href="#make-variables-→-cli-flags" aria-label="Permalink to &quot;Make variables → CLI flags&quot;">​</a></h2><p>The Makefile is the source of truth. All commands are invoked via <code>make &lt;target&gt;</code>; the CLI receives variables as flags.</p><table tabindex="0"><thead><tr><th>Make variable</th><th>CLI flag / behaviour</th><th>Example</th></tr></thead><tbody><tr><td><code>BRAND</code></td><td>First positional arg (defaults to config brand); for <code>make switch</code>: target brand (omit to toggle)</td><td><code>make pull</code>; <code>make switch BRAND=ann</code></td></tr><tr><td><code>DATE</code></td><td><code>--date=YYYY-MM-DD</code></td><td><code>make refresh DATE=2026-02-14</code></td></tr><tr><td><code>REFRESH</code></td><td><code>--refresh=r1</code></td><td><code>make push REFRESH=r2</code></td></tr><tr><td><code>FORCE=1</code></td><td><code>--force</code> (force rebuild/re-push; skip delete confirmation)</td><td><code>make push FORCE=1</code>; <code>make delete DATE=… FORCE=1</code></td></tr><tr><td><code>YES=1</code></td><td><code>--yes</code> (skip confirmation/approval prompts)</td><td><code>make push-all YES=1</code></td></tr><tr><td><code>ALL=1</code></td><td><code>refresh</code>/<code>push</code>: <code>--all-refreshes</code> (all refreshes in a date); <code>status</code>: <code>--all</code> (full history)</td><td><code>make status ALL=1</code></td></tr><tr><td><code>FAIL_FAST=1</code></td><td>Stop <code>build-all</code>/<code>push-all</code> on first failure (default: continue)</td><td><code>make build-all FAIL_FAST=1</code></td></tr><tr><td><code>ARGS=&quot;...&quot;</code></td><td>Pass extra CLI flags (appended after mapped vars)</td><td><code>make push ARGS=&quot;--yes --force&quot;</code></td></tr><tr><td><code>SKIP_FETCH=1</code></td><td><code>--skip-fetch</code></td><td><code>make pull SKIP_FETCH=1</code></td></tr><tr><td><code>CONVERT=1</code></td><td><code>--convert</code></td><td><code>make pull CONVERT=1</code></td></tr><tr><td><code>STATUS_REFRESH_INDEX</code></td><td>status (non-TTY): 0-based index of refresh row to act on</td><td><code>STATUS_REFRESH_INDEX=2 make status</code></td></tr><tr><td><code>STATUS_ACTION_INDEX</code></td><td>status (non-TTY): 0-based index of action (0=Build refresh, 1=Push to staging, 2=Upload assets, 3=Delete refresh, 4=Refresh detail, 5=Pull).</td><td><code>STATUS_ACTION_INDEX=1 make status</code></td></tr><tr><td><code>VERBOSE=1</code></td><td><code>--verbose</code></td><td><code>make push VERBOSE=1</code></td></tr><tr><td><code>OP</code></td><td>reports operation (<code>report</code>, <code>history</code>, <code>coverage</code>)</td><td><code>make reports OP=report DATE=2026-02-14</code></td></tr></tbody></table><p><strong>Brand switch:</strong> Use <code>make switch</code> to toggle loft ↔ ann (no args). Use <code>make switch BRAND=ann</code> for a specific brand. Use <code>make setup</code> for full wizard.</p><h2 id="shared-cli-flags" tabindex="-1">Shared CLI flags <a class="header-anchor" href="#shared-cli-flags" aria-label="Permalink to &quot;Shared CLI flags&quot;">​</a></h2><p>Most commands support: <code>--force</code>, <code>-y/--yes</code>, <code>--dry-run</code>, <code>--verbose</code>, <code>--date</code>, <code>--refresh</code>, <code>--no-interactive</code>, <code>--strict</code>. See per-command pages for command-specific flags. Run <code>make &lt;command&gt; ARGS=&quot;--help&quot;</code> for full usage.</p><h2 id="cli-arguments" tabindex="-1">CLI arguments <a class="header-anchor" href="#cli-arguments" aria-label="Permalink to &quot;CLI arguments&quot;">​</a></h2><p>Most commands take <code>[brand] [target]</code> — brand (loft, ann) and target (date, path, or operation). Brand defaults to config; target varies by command (date/path for refresh/push, campaign prefix for upload, zone for reports history). Use <code>make &lt;command&gt; ARGS=&quot;--help&quot;</code> to see per-command args.</p><h2 id="per-command-pages" tabindex="-1">Per-command pages <a class="header-anchor" href="#per-command-pages" aria-label="Permalink to &quot;Per-command pages&quot;">​</a></h2><ul><li><strong>Producer:</strong> <a href="/ocapi-docs.github.io/cli/status.html">status</a> · <a href="/ocapi-docs.github.io/cli/pull.html">pull</a> · <a href="/ocapi-docs.github.io/cli/build.html">build</a> · <a href="/ocapi-docs.github.io/cli/push.html">push</a>. Sticky selection: <a href="/ocapi-docs.github.io/glossary.html#sticky-selection-active-refresh">Glossary#sticky-selection</a>.</li><li><strong>Dev &amp; Ops:</strong> <a href="/ocapi-docs.github.io/cli/setup.html">setup</a> · <a href="/ocapi-docs.github.io/cli/upload.html">upload</a> · <a href="/ocapi-docs.github.io/cli/delete.html">delete</a> · <a href="/ocapi-docs.github.io/cli/reports.html">reports</a></li></ul><p>For full workflow and example output, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>. For a walkthrough of blocking errors and approval steps, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>.</p>',20)])])}const p=t(r,[["render",c]]);export{h as __pageData,p as default};
